// Package auth 提供密码哈希与访问令牌。
package auth

import (
	"crypto/hmac"
	"crypto/rand"
	"crypto/sha256"
	"crypto/subtle"
	"encoding/base64"
	"encoding/binary"
	"errors"
	"fmt"
	"strconv"
	"strings"
)

const (
	pbkdf2Iterations = 210000
	pbkdf2KeyLen     = 32
	pbkdf2SaltLen    = 16
	hashScheme       = "pbkdf2_sha256"
)

// HashPassword 返回可存库的密码编码。
func HashPassword(password string) (string, error) {
	if password == "" {
		return "", errors.New("密码不能为空")
	}
	salt := make([]byte, pbkdf2SaltLen)
	if _, err := rand.Read(salt); err != nil {
		return "", fmt.Errorf("生成盐失败: %w", err)
	}
	dk := pbkdf2KeySHA256([]byte(password), salt, pbkdf2Iterations, pbkdf2KeyLen)
	return fmt.Sprintf("%s$%d$%s$%s", hashScheme, pbkdf2Iterations,
		base64.RawStdEncoding.EncodeToString(salt),
		base64.RawStdEncoding.EncodeToString(dk)), nil
}

// VerifyPassword 常量时间比较。
func VerifyPassword(encoded, password string) bool {
	parts := strings.Split(encoded, "$")
	if len(parts) != 4 || parts[0] != hashScheme {
		return false
	}
	iter, err := strconv.Atoi(parts[1])
	if err != nil || iter <= 0 || iter > 10_000_000 {
		return false
	}
	salt, err := base64.RawStdEncoding.DecodeString(parts[2])
	if err != nil {
		return false
	}
	want, err := base64.RawStdEncoding.DecodeString(parts[3])
	if err != nil || len(want) == 0 {
		return false
	}
	got := pbkdf2KeySHA256([]byte(password), salt, iter, len(want))
	return subtle.ConstantTimeCompare(got, want) == 1
}

// pbkdf2KeySHA256 是 RFC 8018 定义的 PBKDF2，PRF 为 HMAC-SHA256。
func pbkdf2KeySHA256(password, salt []byte, iterations, keyLen int) []byte {
	mac := hmac.New(sha256.New, password)
	hashLen := mac.Size()
	blocks := (keyLen + hashLen - 1) / hashLen
	derived := make([]byte, 0, blocks*hashLen)

	u := make([]byte, hashLen)
	t := make([]byte, hashLen)
	for block := 1; block <= blocks; block++ {
		mac.Reset()
		mac.Write(salt)
		var idx [4]byte
		binary.BigEndian.PutUint32(idx[:], uint32(block))
		mac.Write(idx[:])
		copy(u, mac.Sum(nil))
		copy(t, u)
		for n := 1; n < iterations; n++ {
			mac.Reset()
			mac.Write(u)
			copy(u, mac.Sum(nil))
			for i := range t {
				t[i] ^= u[i]
			}
		}
		derived = append(derived, t...)
	}
	return derived[:keyLen]
}
```

Wait: `copy(u, mac.Sum(nil))` — mac.Sum(nil) returns new slice; copy into u. Then subsequent `mac.Write(u)` uses u. Good. But `copy(u, mac.Sum(nil))` allocates each iteration. Fine. Could optimize with `mac.Sum(u[:0])`. Let me use `u = mac.Sum(u[:0])`? Careful: `mac.Sum(u[:0])` appends to u[:0] and returns slice; since cap(u)=hashLen, it reuses. That's fine and avoids allocation. But `mac.Sum` doesn't reset mac. We reset before. Let me write:

```go
for block := 1; block <= blocks; block++ {
    mac.Reset()
    mac.Write(salt)
    mac.Write(idx)
    u = mac.Sum(u[:0])
    copy(t, u)
    for n := 1; n < iterations; n++ {
        mac.Reset()
        mac.Write(u)
        u = mac.Sum(u[:0])
        for i := range t {
            t[i] ^= u[i]
        }
    }
    derived = append(derived, t...)
}
```
This is correct: after `u = mac.Sum(u[:0])`, u has length hashLen. Writing mac with u then `mac.Sum(u[:0])` — does mac.Sum read the underlying array while appending? `Sum` appends to b (u[:0]) after computing the hash internally; it doesn't read b's contents. So safe. Good.

Wait, subtle bug: `mac.Write(u)` then `mac.Sum(u[:0])`. `Sum` computes hash of data written so far and appends. It does not use b as input. Safe.

But `copy(t, u)` then in loop `t[i] ^= u[i]`. Good.

