// Package config 从环境变量加载服务配置。
package config

import (
	"crypto/rand"
	"errors"
	"fmt"
	"os"
	"time"
)

// 默认值只在开发环境使用；一旦生效，DevDefaults 会被置为 true，由调用方告警。
const (
	defaultAddr          = ":8080"
	defaultAdminUsername = "admin"
	defaultAdminPassword = "admin123"
	defaultTokenTTL      = 12 * time.Hour
)

// Config 是进程启动所需的全部配置。
type Config struct {
	Addr          string
	TokenSecret   []byte
	TokenTTL      time.Duration
	AdminUsername string
	AdminPassword string
	// DevDefaults 为 true 表示密码或令牌密钥用了内置默认值。
	DevDefaults bool
}

// Load 读取环境变量并填充默认值。缺少密码或令牌密钥时会退回到开发默认值，
// 并通过 DevDefaults 提醒调用方，而不是直接拒绝启动。
func Load() (Config, error) {
	cfg := Config{
		Addr:          envOr("ADMIN_ADDR", defaultAddr),
		AdminUsername: envOr("ADMIN_USERNAME", defaultAdminUsername),
	}

	ttl, err := time.ParseDuration(envOr("ADMIN_TOKEN_TTL", defaultTokenTTL.String()))
	if err != nil {
		return Config{}, fmt.Errorf("ADMIN_TOKEN_TTL 不是合法时长: %w", err)
	}
	if ttl <= 0 {
		return Config{}, errors.New("ADMIN_TOKEN_TTL 必须为正数")
	}
	cfg.TokenTTL = ttl

	if cfg.AdminPassword = os.Getenv("ADMIN_PASSWORD"); cfg.AdminPassword == "" {
		cfg.AdminPassword = defaultAdminPassword
		cfg.DevDefaults = true
	}

	if secret := os.Getenv("ADMIN_TOKEN_SECRET"); secret != "" {
		cfg.TokenSecret = []byte(secret)
	} else {
		buf := make([]byte, 32)
		if _, err := rand.Read(buf); err != nil {
			return Config{}, fmt.Errorf("生成令牌密钥失败: %w", err)
		}
		cfg.TokenSecret = buf
		cfg.DevDefaults = true
	}

	return cfg, nil
}

func envOr(key, fallback string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return fallback
}

// Package idgen 生成随机的十六进制标识符。
package idgen

import (
	"crypto/rand"
	"encoding/hex"
)

// New 返回 16 字节随机数的十六进制编码。
func New() string {
	buf := make([]byte, 16)
	if _, err := rand.Read(buf); err != nil {
		// crypto/rand 在受支持的平台上不会失败；失败意味着进程已无法安全继续。
		panic("idgen: 系统随机源不可用: " + err.Error())
	}
	return hex.EncodeToString(buf)
}

// Package auth 提供密码哈希与访问令牌。
package auth

import (
	"crypto/hmac"
	"crypto/rand"
	"crypto/sha256"
	"crypto/subtle"
	"encoding/base64"
	"encoding/binary"
	"errors"
	"fmt"
	"strconv"
	"strings"
)

// 密码编码格式为 pbkdf2_sha256$<迭代次数>$<base64盐>$<base64派生密钥>。
const (
	pbkdf2Scheme     = "pbkdf2_sha256"
	pbkdf2Iterations = 210_000
	pbkdf2KeyLen     = 32
	pbkdf2SaltLen    = 16
)

// HashPassword 生成带随机盐的密码编码，可直接存库。
func HashPassword(password string) (string, error) {
	if password == "" {
		return "", errors.New("密码不能为空")
	}
	salt := make([]byte, pbkdf2SaltLen)
	if _, err := rand.Read(salt); err != nil {
		return "", fmt.Errorf("生成盐失败: %w", err)
	}
	dk := pbkdf2KeySHA256([]byte(password), salt, pbkdf2Iterations, pbkdf2KeyLen)
	return fmt.Sprintf("%s$%d$%s$%s", pbkdf2Scheme, pbkdf2Iterations,
		base64.RawStdEncoding.EncodeToString(salt),
		base64.RawStdEncoding.EncodeToString(dk)), nil
}

// VerifyPassword 用常量时间比较校验密码，编码非法时返回 false。
func VerifyPassword(encoded, password string) bool {
	parts := strings.Split(encoded, "$")
	if len(parts) != 4 || parts[0] != pbkdf2Scheme {
		return false
	}
	iterations, err := strconv.Atoi(parts[1])
	if err != nil || iterations <= 0 || iterations > 10_000_000 {
		return false
	}
	salt, err := base64.RawStdEncoding.DecodeString(parts[2])
	if err != nil {
		return false
	}
	want, err := base64.RawStdEncoding.DecodeString(parts[3])
	if err != nil || len(want) == 0 {
		return false
	}
	got := pbkdf2KeySHA256([]byte(password), salt, iterations, len(want))
	return subtle.ConstantTimeCompare(got, want) == 1
}

// pbkdf2KeySHA256 是 RFC 8018 定义的 PBKDF2，伪随机函数为 HMAC-SHA256。
// 自行实现是为了让本仓库只依赖标准库。
func pbkdf2KeySHA256(password, salt []byte, iterations, keyLen int) []byte {
	mac := hmac.New(sha256.New, password)
	hashLen := mac.Size()
	blocks := (keyLen + hashLen - 1) / hashLen
	derived := make([]byte, 0, blocks*hashLen)

	u := make([]byte, hashLen)
	t := make([]byte, hashLen)
	var blockIndex [4]byte
	for block := 1; block <= blocks; block++ {
		mac.Reset()
		mac.Write(salt)
		binary.BigEndian.PutUint32(blockIndex[:], uint32(block))
		mac.Write(blockIndex[:])
		u = mac.Sum(u[:0])
		copy(t, u)

		for n := 1; n < iterations; n++ {
			mac.Reset()
			mac.Write(u)
			u = mac.Sum(u[:0])
			for i := range t {
				t[i] ^= u[i]
			}
		}
		derived = append(derived, t...)
	}
	return derived[:keyLen]
}

package auth

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/base64"
	"encoding/json"
	"errors"
	"strings"
	"sync"
	"time"

	"admin/internal/idgen"
)

// 令牌校验可能返回的错误。
var (
	ErrInvalidToken = errors.New("令牌无效")
	ErrExpiredToken = errors.New("令牌已过期")
	ErrRevokedToken = errors.New("令牌已注销")
)

// Claims 是令牌负载。字段刻意保持精简。
type Claims struct {
	Subject   string `json:"sub"`
	Username  string `json:"usr"`
	Role      string `json:"role"`
	IssuedAt  int64  `json:"iat"`
	ExpiresAt int64  `json:"exp"`
	ID        string `json:"jti"`
}

// TokenManager 用 HMAC-SHA256 签发并校验无状态令牌，另用内存表维护注销名单。
type TokenManager struct {
	secret []byte
	ttl    time.Duration
	now    func() time.Time

	mu      sync.Mutex
	revoked map[string]time.Time
}

// NewTokenManager 构造令牌管理器。secret 为空是调用方的错误，这里直接 panic，
// 避免签发无法校验的令牌。
func NewTokenManager(secret []byte, ttl time.Duration) *TokenManager {
	if len(secret) == 0 {
		panic("auth: 令牌密钥不能为空")
	}
	if ttl <= 0 {
		panic("auth: 令牌有效期必须为正数")
	}
	return &TokenManager{
		secret:  secret,
		ttl:     ttl,
		now:     time.Now,
		revoked: make(map[string]time.Time),
	}
}

// Issue 为指定用户签发令牌，并返回其负载。
func (m *TokenManager) Issue(subject, username, role string) (string, Claims, error) {
	now := m.now()
	claims := Claims{
		Subject:   subject,
		Username:  username,
		Role:      role,
		IssuedAt:  now.Unix(),
		ExpiresAt: now.Add(m.ttl).Unix(),
		ID:        idgen.New(),
	}
	payload, err := json.Marshal(claims)
	if err != nil {
		return "", Claims{}, err
	}
	body := base64.RawURLEncoding.EncodeToString(payload)
	return body + "." + base64.RawURLEncoding.EncodeToString(m.sign(body)), claims, nil
}

// Parse 校验签名、有效期与注销状态，成功时返回负载。
func (m *TokenManager) Parse(token string) (*Claims, error) {
	body, sigPart, ok := strings.Cut(token, ".")
	if !ok || body == "" || sigPart == "" {
		return nil, ErrInvalidToken
	}
	sig, err := base64.RawURLEncoding.DecodeString(sigPart)
	if err != nil || !hmac.Equal(sig, m.sign(body)) {
		return nil, ErrInvalidToken
	}
	payload, err := base64.RawURLEncoding.DecodeString(body)
	if err != nil {
		return nil, ErrInvalidToken
	}
	var claims Claims
	if err := json.Unmarshal(payload, &claims); err != nil {
		return nil, ErrInvalidToken
	}
	if claims.Subject == "" || claims.ID == "" {
		return nil, ErrInvalidToken
	}
	if m.now().Unix() >= claims.ExpiresAt {
		return nil, ErrExpiredToken
	}
	m.mu.Lock()
	defer m.mu.Unlock()
	if _, ok := m.revoked[claims.ID]; ok {
		return nil, ErrRevokedToken
	}
	return &claims, nil
}

// Revoke 把令牌加入注销名单；顺带清理已过期的条目，避免名单无界增长。
func (m *TokenManager) Revoke(id string, expiresAt time.Time) {
	m.mu.Lock()
	defer m.mu.Unlock()
	m.revoked[id] = expiresAt
	now := m.now()
	for key, exp := range m.revoked {
		if now.After(exp) {
			delete(m.revoked, key)
		}
	}
}

func (m *TokenManager) sign(body string) []byte {
	mac := hmac.New(sha256.New, m.secret)
	mac.Write([]byte(body))
	return mac.Sum(nil)
}

// Package store 提供线程安全的内存用户与角色仓库，并实现基于角色的权限判断。
//
// 仓库只保存密码哈希；明文密码由调用方在进入这里之前完成哈希。
package store

import (
	"errors"
	"fmt"
	"sort"
	"strings"
	"sync"
	"time"

	"admin/internal/idgen"
)

// 仓库对外可能返回的错误。
var (
	ErrNotFound  = errors.New("资源不存在")
	ErrConflict  = errors.New("资源已存在")
	ErrLastAdmin = errors.New("不能移除最后一个可用的管理员")
)

// 内置角色名。
const (
	RoleAdmin    = "admin"
	RoleOperator = "operator"
	RoleViewer   = "viewer"
)

// 权限标识。内置 admin 角色持有通配符 "*"。
const (
	PermUserRead   = "user:read"
	PermUserWrite  = "user:write"
	PermUserDelete = "user:delete"
	PermRoleRead   = "role:read"
	PermRoleWrite  = "role:write"
)

// User 是存储层的用户记录。PasswordHash 永远不序列化给客户端。
type User struct {
	ID           string    `json:"id"`
	Username     string    `json:"username"`
	PasswordHash string    `json:"-"`
	Role         string    `json:"role"`
	Active       bool      `json:"active"`
	CreatedAt    time.Time `json:"created_at"`
	UpdatedAt    time.Time `json:"updated_at"`
}

// Role 是一组权限的命名集合。
type Role struct {
	Name        string   `json:"name"`
	Permissions []string `json:"permissions"`
	Builtin     bool     `json:"builtin"`
}

// UpdateInput 描述一次局部更新；nil 字段保持不变。
type UpdateInput struct {
	Role         *string
	Active       *bool
	PasswordHash *string
}

// Store 是内存仓库。所有导出方法都可并发调用。
type Store struct {
	mu        sync.RWMutex
	users     map[string]*User
	usernames map[string]string // 小写用户名 -> 用户 ID
	roles     map[string]*Role
	now       func() time.Time
}

// New 返回一个空仓库。
func New() *Store {
	return &Store{
		users:     make(map[string]*User),
		usernames: make(map[string]string),
		roles:     make(map[string]*Role),
		now:       time.Now,
	}
}

// SeedBuiltinRoles 幂等地写入 admin / operator / viewer 三个内置角色。
func (s *Store) SeedBuiltinRoles() {
	_, _ = s.CreateRole(RoleAdmin, []string{"*"}, true)
	_, _ = s.CreateRole(RoleOperator, []string{PermUserRead, PermUserWrite, PermRoleRead}, true)
	_, _ = s.CreateRole(RoleViewer, []string{PermUserRead, PermRoleRead}, true)
}

// CreateUser 新增用户，用户名大小写不敏感地唯一。
func (s *Store) CreateUser(username, passwordHash, role string) (User, error) {
	username = strings.TrimSpace(username)
	if username == "" {
		return User{}, errors.New("用户名不能为空")
	}
	key := strings.ToLower(username)

	s.mu.Lock()
	defer s.mu.Unlock()
	if _, exists := s.usernames[key]; exists {
		return User{}, ErrConflict
	}
	if _, exists := s.roles[role]; !exists {
		return User{}, fmt.Errorf("%w: 角色 %q", ErrNotFound, role)
	}
	now := s.now()
	u := &User{
		ID:           idgen.New(),
		Username:     username,
		PasswordHash: passwordHash,
		Role:         role,
		Active:       true,
		CreatedAt:    now,
		UpdatedAt:    now,
	}
	s.users[u.ID] = u
	s.usernames[key] = u.ID
	return *u, nil
}

// GetUser 按 ID 查询。
func (s *Store) GetUser(id string) (User, error) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	u, ok := s.users[id]
	if !ok {
		return User{}, ErrNotFound
	}
	return *u, nil
}

// GetUserByUsername 按用户名查询，大小写不敏感。
func (s *Store) GetUserByUsername(username string) (User, error) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	id, ok := s.usernames[strings.ToLower(strings.TrimSpace(username))]
	if !ok {
		return User{}, ErrNotFound
	}
	return *s.users[id], nil
}

// ListUsers 返回按创建时间排序的一页用户，以及总数。
func (s *Store) ListUsers(offset, limit int) ([]User, int) {
	s.mu.RLock()
	defer s.mu.RUnlock()

	all := make([]User, 0, len(s.users))
	for _, u := range s.users {
		all = append(all, *u)
	}
	sort.Slice(all, func(i, j int) bool {
		if !all[i].CreatedAt.Equal(all[j].CreatedAt) {
			return all[i].CreatedAt.Before(all[j].CreatedAt)
		}
		return all[i].ID < all[j].ID
	})

	total := len(all)
	if offset < 0 {
		offset = 0
	}
	if offset >= total {
		return []User{}, total
	}
	end := total
	if limit > 0 && offset+limit < total {
		end = offset + limit
	}
	return all[offset:end], total
}

// UpdateUser 局部更新用户，并保护最后一个可用管理员不被降级或停用。
func (s *Store) UpdateUser(id string, in UpdateInput) (User, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	u, ok := s.users[id]
	if !ok {
		return User{}, ErrNotFound
	}

	nextRole := u.Role
	if in.Role != nil {
		if _, exists := s.roles[*in.Role]; !exists {
			return User{}, fmt.Errorf("%w: 角色 %q", ErrNotFound, *in.Role)
		}
		nextRole = *in.Role
	}
	nextActive := u.Active
	if in.Active != nil {
		nextActive = *in.Active
	}

	if u.Role == RoleAdmin && u.Active && (nextRole != RoleAdmin || !nextActive) {
		if s.countActiveAdminsLocked() <= 1 {
			return User{}, ErrLastAdmin
		}
	}

	if in.PasswordHash != nil {
		u.PasswordHash = *in.PasswordHash
	}
	u.Role = nextRole
	u.Active = nextActive
	u.UpdatedAt = s.now()
	return *u, nil
}

// DeleteUser 删除用户，并保护最后一个可用管理员不被删除。
func (s *Store) DeleteUser(id string) error {
	s.mu.Lock()
	defer s.mu.Unlock()

	u, ok := s.users[id]
	if !ok {
		return ErrNotFound
	}
	if u.Role == RoleAdmin && u.Active && s.countActiveAdminsLocked() <= 1 {
		return ErrLastAdmin
	}
	delete(s.users, id)
	delete(s.usernames, strings.ToLower(u.Username))
	return nil
}

func (s *Store) countActiveAdminsLocked() int {
	count := 0
	for _, u := range s.users {
		if u.Role == RoleAdmin && u.Active {
			count++
		}
	}
	return count
}

// CreateRole 新增角色，权限列表会去重并忽略空白项。
func (s *Store) CreateRole(name string, permissions []string, builtin bool) (Role, error) {
	name = strings.TrimSpace(name)
	if name == "" {
		return Role{}, errors.New("角色名不能为空")
	}
	seen := make(map[string]bool, len(permissions))
	perms := make([]string, 0, len(permissions))
	for _, p := range permissions {
		p = strings.TrimSpace(p)
		if p == "" || seen[p] {
			continue
		}
		seen[p] = true
		perms = append(perms, p)
	}

	s.mu.Lock()
	defer s.mu.Unlock()
	if _, exists := s.roles[name]; exists {
		return Role{}, ErrConflict
	}
	r := &Role{Name: name, Permissions: perms, Builtin: builtin}
	s.roles[name] = r
	return *r, nil
}

// GetRole 按名称查询角色。
func (s *Store) GetRole(name string) (Role, error) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	r, ok := s.roles[name]
	if !ok {
		return Role{}, ErrNotFound
	}
	return copyRole(r), nil
}

// ListRoles 返回按名称排序的全部角色。
func (s *Store) ListRoles() []Role {
	s.mu.RLock()
	defer s.mu.RUnlock()
	roles := make([]Role, 0, len(s.roles))
	for _, r := range s.roles {
		roles = append(roles, copyRole(r))
	}
	sort.Slice(roles, func(i, j int) bool { return roles[i].Name < roles[j].Name })
	return roles
}

// HasPermission 判断角色是否持有指定权限，通配符 "*" 视为持有全部权限。
func (s *Store) HasPermission(role, permission string) bool {
	s.mu.RLock()
	defer s.mu.RUnlock()
	r, ok := s.roles[role]
	if !ok {
		return false
	}
	for _, p := range r.Permissions {
		if p == "*" || p == permission {
			return true
		}
	}
	return false
}

func copyRole(r *Role) Role {
	perms := make([]string, len(r.Permissions))
	copy(perms, r.Permissions)
	return Role{Name: r.Name, Permissions: perms, Builtin: r.Builtin}
}

package api

import (
	"net/http"
	"strings"
)

// Handler 是带路径参数的 HTTP 处理器。
type Handler func(w http.ResponseWriter, r *http.Request, params map[string]string)

type route struct {
	method   string
	segments []string
	handler  Handler
}

// Router 是一个最小的方法感知路由器，支持 ":name" 形式的路径参数。
// 之所以不用 net/http 1.22 起的方法路由模式，是为了让本模块在 go 1.21 下也能编译。
type Router struct {
	routes []route
}

// NewRouter 返回空路由器。
func NewRouter() *Router { return &Router{} }

// Handle 注册一条路由。pattern 形如 "/api/v1/users/:id"。
func (rt *Router) Handle(method, pattern string, h Handler) {
	rt.routes = append(rt.routes, route{
		method:   method,
		segments: splitPath(pattern),
		handler:  h,
	})
}

// ServeHTTP 依次匹配路径与方法；路径命中但方法不符时返回 405。
func (rt *Router) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	actual := splitPath(r.URL.Path)
	methodMismatch := false
	for _, ro := range rt.routes {
		params, ok := matchSegments(ro.segments, actual)
		if !ok {
			continue
		}
		if ro.method != r.Method {
			methodMismatch = true
			continue
		}
		ro.handler(w, r, params)
		return
	}
	if methodMismatch {
		w.Header().Set("Allow", strings.Join(rt.allowedMethods(actual), ", "))
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "请求方法不被支持")
		return
	}
	writeError(w, http.StatusNotFound, "not_found", "资源不存在")
}

func (rt *Router) allowedMethods(actual []string) []string {
	var methods []string
	for _, ro := range rt.routes {
		if _, ok := matchSegments(ro.segments, actual); ok {
			methods = append(methods, ro.method)
		}
	}
	return methods
}

func splitPath(p string) []string {
	p = strings.Trim(p, "/")
	if p == "" {
		return nil
	}
	return strings.Split(p, "/")
}

func matchSegments(pattern, actual []string) (map[string]string, bool) {
	if len(pattern) != len(actual) {
		return nil, false
	}
	var params map[string]string
	for i := range pattern {
		if name, ok := strings.CutPrefix(pattern[i], ":"); ok {
			if params == nil {
				params = make(map[string]string, 1)
			}
			params[name] = actual[i]
			continue
		}
		if pattern[i] != actual[i] {
			return nil, false
		}
	}
	return params, true
}

package api

import (
	"context"
	"log/slog"
	"net/http"
	"strings"
	"time"

	"admin/internal/auth"
)

// Middleware 包装处理器。
type Middleware func(Handler) Handler

// chain 按声明顺序自外向内包装处理器。
func chain(h Handler, mws ...Middleware) Handler {
	for i := len(mws) - 1; i >= 0; i-- {
		h = mws[i](h)
	}
	return h
}

type contextKey int

const claimsContextKey contextKey = iota

func withClaims(ctx context.Context, claims *auth.Claims) context.Context {
	return context.WithValue(ctx, claimsContextKey, claims)
}

func claimsFrom(ctx context.Context) (*auth.Claims, bool) {
	claims, ok := ctx.Value(claimsContextKey).(*auth.Claims)
	return claims, ok
}

type statusRecorder struct {
	http.ResponseWriter
	status int
}

func (r *statusRecorder) WriteHeader(code int) {
	r.status = code
	r.ResponseWriter.WriteHeader(code)
}

// recoverer 兜住处理器 panic，返回 500 而不是断开连接。
func (s *Server) recoverer(next Handler) Handler {
	return func(w http.ResponseWriter, r *http.Request, params map[string]string) {
		defer func() {
			if rec := recover(); rec != nil {
				s.logger.Error("处理请求时 panic", "panic", rec, "method", r.Method, "path", r.URL.Path)
				writeError(w, http.StatusInternalServerError, "internal_error", "服务内部错误")
			}
		}()
		next(w, r, params)
	}
}

// requestLogger 记录每次请求的方法、路径、状态码与耗时。
func (s *Server) requestLogger(next Handler) Handler {
	return func(w http.ResponseWriter, r *http.Request, params map[string]string) {
		start := time.Now()
		rec := &statusRecorder{ResponseWriter: w, status: http.StatusOK}
		next(rec, r, params)
		s.logger.LogAttrs(r.Context(), slog.LevelInfo, "http 请求",
			slog.String("method", r.Method),
			slog.String("path", r.URL.Path),
			slog.Int("status", rec.status),
			slog.Duration("elapsed", time.Since(start)),
		)
	}
}

// authenticate 校验 Bearer 令牌，并把负载放进请求上下文。
func (s *Server) authenticate(next Handler) Handler {
	return func(w http.ResponseWriter, r *http.Request, params map[string]string) {
		token, ok := bearerToken(r)
		if !ok {
			writeError(w, http.StatusUnauthorized, "unauthorized", "缺少 Bearer 访问令牌")
			return
		}
		claims, err := s.tokens.Parse(token)
		if err != nil {
			writeError(w, http.StatusUnauthorized, "unauthorized", "访问令牌无效或已过期")
			return
		}
		next(w, r.WithContext(withClaims(r.Context(), claims)), params)
	}
}

// requirePermission 要求当前角色持有指定权限。
func (s *Server) requirePermission(permission string) Middleware {
	return func(next Handler) Handler {
		return func(w http.ResponseWriter, r *http.Request, params map[string]string) {
			claims, ok := claimsFrom(r.Context())
			if !ok {
				writeError(w, http.StatusUnauthorized, "unauthorized", "缺少访问令牌")
				return
			}
			if !s.store.HasPermission(claims.Role, permission) {
				writeError(w, http.StatusForbidden, "forbidden", "当前角色无权执行该操作")
				return
			}
			next(w, r, params)
		}
	}
}

func bearerToken(r *http.Request) (string, bool) {
	header := r.Header.Get("Authorization")
	const prefix = "Bearer "
	if len(header) <= len(prefix) || !strings.EqualFold(header[:len(prefix)], prefix) {
		return "", false
	}
	token := strings.TrimSpace(header[len(prefix):])
	return token, token != ""
}

package api

import (
	"encoding/json"
	"net/http"
	"strconv"
)

const maxBodyBytes = 1 << 20 // 1 MiB

type errorEnvelope struct {
	Error errorDetail `json:"error"`
}

type errorDetail struct {
	Code    string `json:"code"`
	Message string `json:"message"`
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(status)
	if v == nil {
		return
	}
	_ = json.NewEncoder(w).Encode(v)
}

func writeError(w http.ResponseWriter, status int, code, message string) {
	writeJSON(w, status, errorEnvelope{Error: errorDetail{Code: code, Message: message}})
}

// decodeJSON 读取并解析请求体；失败时已写出 400，调用方直接返回即可。
func decodeJSON(w http.ResponseWriter, r *http.Request, dst any) bool {
	r.Body = http.MaxBytesReader(w, r.Body, maxBodyBytes)
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields()
	if err := dec.Decode(dst); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "请求体不是合法 JSON")
		return false
	}
	return true
}

// queryInt 解析查询参数并夹在 [min, max] 内，缺失或非法时返回 fallback。
func queryInt(r *http.Request, key string, fallback, min, max int) int {
	raw := r.URL.Query().Get(key)
	if raw == "" {
		return fallback
	}
	n, err := strconv.Atoi(raw)
	if err != nil {
		return fallback
	}
	if n < min {
		return min
	}
	if n > max {
		return max
	}
	return n
}

