func (s *Server) handleHealth(w http.ResponseWriter, _ *http.Request, _ map[string]string) {
	writeJSON(w, http.StatusOK, map[string]any{
		"status":  "ok",
		"version": version.String(),
	})
}

// ---------- 认证 ----------

type loginRequest struct {
	Username string `json:"username"`
	Password string `json:"password"`
}

type loginResponse struct {
	Token     string     `json:"token"`
	ExpiresAt time.Time  `json:"expires_at"`
	User      store.User `json:"user"`
}

func (s *Server) handleLogin(w http.ResponseWriter, r *http.Request, _ map[string]string) {
	var req loginRequest
	if !decodeJSON(w, r, &req) {
		return
	}
	req.Username = strings.TrimSpace(req.Username)
	if req.Username == "" || req.Password == "" {
		writeError(w, http.StatusBadRequest, "invalid_argument", "用户名和密码不能为空")
		return
	}

	user, err := s.store.GetUserByUsername(req.Username)
	if err != nil || !auth.VerifyPassword(user.PasswordHash, req.Password) {
		// 用户名不存在与密码错误返回同一结果，避免枚举账号。
		writeError(w, http.StatusUnauthorized, "invalid_credentials", "用户名或密码错误")
		return
	}
	if !user.Active {
		writeError(w, http.StatusForbidden, "account_disabled", "账号已被停用")
		return
	}

	token, claims, err := s.tokens.Issue(user.ID, user.Username, user.Role)
	if err != nil {
		s.fail(w, err)
		return
	}
	writeJSON(w, http.StatusOK, loginResponse{
		Token:     token,
		ExpiresAt: time.Unix(claims.ExpiresAt, 0).UTC(),
		User:      user,
	})
}

func (s *Server) handleLogout(w http.ResponseWriter, r *http.Request, _ map[string]string) {
	claims, ok := claimsFrom(r.Context())
	if !ok {
		writeError(w, http.StatusUnauthorized, "unauthorized", "缺少访问令牌")
		return
	}
	s.tokens.Revoke(claims.ID, time.Unix(claims.ExpiresAt, 0))
	writeJSON(w, http.StatusOK, map[string]string{"status": "logged_out"})
}

func (s *Server) handleMe(w http.ResponseWriter, r *http.Request, _ map[string]string) {
	claims, ok := claimsFrom(r.Context())
	if !ok {
		writeError(w, http.StatusUnauthorized, "unauthorized", "缺少访问令牌")
		return
	}
	user, err := s.store.GetUser(claims.Subject)
	if err != nil {
		writeError(w, http.StatusUnauthorized, "unauthorized", "账号不存在")
		return
	}
	writeJSON(w, http.StatusOK, user)
}

// ---------- 用户 ----------

func (s *Server) handleListUsers(w http.ResponseWriter, r *http.Request, _ map[string]string) {
	page := queryInt(r, "page", 1, 1, 1_000_000)
	pageSize := queryInt(r, "page_size", 20, 1, 100)
	users, total := s.store.ListUsers((page-1)*pageSize, pageSize)
	writeJSON(w, http.StatusOK, map[string]any{
		"items":     users,
		"total":     total,
		"page":      page,
		"page_size": pageSize,
	})
}

type createUserRequest struct {
	Username string `json:"username"`
	Password string `json:"password"`
	Role     string `json:"role"`
}

func (s *Server) handleCreateUser(w http.ResponseWriter, r *http.Request, _ map[string]string) {
	var req createUserRequest
	if !decodeJSON(w, r, &req) {
		return
	}
	req.Username = strings.TrimSpace(req.Username)
	req.Role = strings.TrimSpace(req.Role)
	if err := validateUsername(req.Username); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_argument", err.Error())
		return
	}
	if err := validatePassword(req.Password); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_argument", err.Error())
		return
	}
	if req.Role == "" {
		writeError(w, http.StatusBadRequest, "invalid_argument", "角色不能为空")
		return
	}

	hash, err := auth.HashPassword(req.Password)
	if err != nil {
		s.fail(w, err)
		return
	}
	user, err := s.store.CreateUser(req.Username, hash, req.Role)
	switch {
	case errors.Is(err, store.ErrConflict):
		writeError(w, http.StatusConflict, "conflict", "用户名已存在")
	case errors.Is(err, store.ErrNotFound):
		writeError(w, http.StatusBadRequest, "invalid_role", "角色不存在")
	case err != nil:
		s.fail(w, err)
	default:
		w.Header().Set("Location", "/api/v1/users/"+user.ID)
		writeJSON(w, http.StatusCreated, user)
	}
}

func (s *Server) handleGetUser(w http.ResponseWriter, _ *http.Request, params map[string]string) {
	user, err := s.store.GetUser(params["id"])
	if errors.Is(err, store.ErrNotFound) {
		writeError(w, http.StatusNotFound, "not_found", "用户不存在")
		return
	}
	if err != nil {
		s.fail(w, err)
		return
	}
	writeJSON(w, http.StatusOK, user)
}

type updateUserRequest struct {
	Password *string `json:"password"`
	Role     *string `json:"role"`
	Active   *bool   `json:"active"`
}

func (s *Server) handleUpdateUser(w http.ResponseWriter, r *http.Request, params map[string]string) {
	var req updateUserRequest
	if !decodeJSON(w, r, &req) {
		return
	}
	if req.Password == nil && req.Role == nil && req.Active == nil {
		writeError(w, http.StatusBadRequest, "invalid_argument", "至少提供一个待更新字段")
		return
	}

	in := store.UpdateInput{Role: req.Role, Active: req.Active}
	if req.Password != nil {
		if err := validatePassword(*req.Password); err != nil {
			writeError(w, http.StatusBadRequest, "invalid_argument", err.Error())
			return
		}
		hash, err := auth.HashPassword(*req.Password)
		if err != nil {
			s.fail(w, err)
			return
		}
		in.PasswordHash = &hash
	}

	user, err := s.store.UpdateUser(params["id"], in)
	switch {
	case errors.Is(err, store.ErrNotFound):
		writeError(w, http.StatusNotFound, "not_found", "用户或角色不存在")
	case errors.Is(err, store.ErrLastAdmin):
		writeError(w, http.StatusConflict, "last_admin", err.Error())
	case err != nil:
		s.fail(w, err)
	default:
		writeJSON(w, http.StatusOK, user)
	}
}

func (s *Server) handleDeleteUser(w http.ResponseWriter, _ *http.Request, params map[string]string) {
	err := s.store.DeleteUser(params["id"])
	switch {
	case errors.Is(err, store.ErrNotFound):
		writeError(w, http.StatusNotFound, "not_found", "用户不存在")
	case errors.Is(err, store.ErrLastAdmin):
		writeError(w, http.StatusConflict, "last_admin", err.Error())
	case err != nil:
		s.fail(w, err)
	default:
		w.WriteHeader(http.StatusNoContent)
	}
}

