}

// ---------- 校验与兜底 ----------

func validateUsername(name string) error {
	if len(name) < 3 || len(name) > 32 {
		return errors.New("用户名长度需为 3-32 个字符")
	}
	for _, r := range name {
		switch {
		case r >= 'a' && r <= 'z', r >= 'A' && r <= 'Z', r >= '0' && r <= '9':
		case r == '_', r == '-', r == '.':
		default:
			return errors.New("用户名只能包含字母、数字、下划线、连字符与点")
		}
	}
	return nil
}

func validatePassword(password string) error {
	if len(password) < 8 || len(password) > 72 {
		return errors.New("密码长度需为 8-72 个字符")
	}
	return nil
}

func (s *Server) fail(w http.ResponseWriter, err error) {
	s.logger.Error("处理请求失败", "err", err)
	writeError(w, http.StatusInternalServerError, "internal_error", "服务内部错误")
}

// Command admin 启动后台管理系统的 HTTP 服务。
package main

import (
	"context"
	"errors"
	"log/slog"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"admin/internal/api"
	"admin/internal/auth"
	"admin/internal/config"
	"admin/internal/store"
	"admin/internal/version"
)

func main() {
	logger := slog.New(slog.NewTextHandler(os.Stdout, &slog.HandlerOptions{Level: slog.LevelInfo}))
	if err := run(logger); err != nil {
		logger.Error("服务异常退出", "err", err)
		os.Exit(1)
	}
}

func run(logger *slog.Logger) error {
	cfg, err := config.Load()
	if err != nil {
		return err
	}
	if cfg.DevDefaults {
		logger.Warn("正在使用开发默认凭据，生产环境请设置 ADMIN_PASSWORD 与 ADMIN_TOKEN_SECRET")
	}

	st := store.New()
	st.SeedBuiltinRoles()
	if err := ensureAdmin(st, cfg.AdminUsername, cfg.AdminPassword); err != nil {
		return err
	}

	tokens := auth.NewTokenManager(cfg.TokenSecret, cfg.TokenTTL)
	handler := api.NewServer(st, tokens, logger)

	srv := &http.Server{
		Addr:              cfg.Addr,
		Handler:           handler,
		ReadHeaderTimeout: 5 * time.Second,
		ReadTimeout:       15 * time.Second,
		WriteTimeout:      15 * time.Second,
		IdleTimeout:       60 * time.Second,
	}

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	errCh := make(chan error, 1)
	go func() {
		logger.Info("admin 服务启动", "addr", cfg.Addr, "version", version.String())
		if err := srv.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
			errCh <- err
		}
	}()

	select {
	case err := <-errCh:
		return err
	case <-ctx.Done():
		logger.Info("收到退出信号，开始优雅关闭")
		shutdownCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
		defer cancel()
		return srv.Shutdown(shutdownCtx)
	}
}

// ensureAdmin 在管理员不存在时创建初始账号。
func ensureAdmin(st *store.Store, username, password string) error {
	if _, err := st.GetUserByUsername(username); err == nil {
		return nil
	} else if !errors.Is(err, store.ErrNotFound) {
		return err
	}
	hash, err := auth.HashPassword(password)
	if err != nil {
		return err
	}
	if _, err := st.CreateUser(username, hash, store.RoleAdmin); err != nil {
		return err
	}
	return nil
}

package auth

import (
	"encoding/hex"
	"strings"
	"testing"
)

// pbkdf2Vectors 是 PBKDF2-HMAC-SHA256 的公开测试向量。
var pbkdf2Vectors = []struct {
	name       string
	password   string
	salt       string
	iterations int
	keyLen     int
	wantHex    string
}{
	{"RFC 7914 基础 c=1", "password", "salt", 1, 32, "120fb6cffcf8b32c43e7225256c4f837a86548c92ccc35480805987cb70be17b"},
	{"RFC 7914 基础 c=2", "password", "salt", 2, 32, "ae4d0c95af6b46d32d0adff928f06dd02a303f8ef3c251dfd6e2d85a95474c43"},
	{"RFC 7914 基础 c=4096", "password", "salt", 4096, 32, "c5e478d59288c841aa530db6845c4c8d962893a001ce4e11a4963873aa98134a"},
	{"长口令与长盐 dkLen=40", "passwordPASSWORDpassword", "saltSALTsaltSALTsaltSALTsaltSALTsalt", 4096, 40, "348c89dbcbd32b2f32d814b8116e84cf2b17347ebc1800181c4e2a1fb8dd53e1c635518c7dac47e9"},
	{"含 NUL 字节 dkLen=16", "pass\x00word", "sa\x00lt", 4096, 16, "89b69d0516f829893c696226650a8687"},
}

func TestPBKDF2KeySHA256Vectors(t *testing.T) {
	for _, v := range pbkdf2Vectors {
		t.Run(v.name, func(t *testing.T) {
			got := pbkdf2KeySHA256([]byte(v.password), []byte(v.salt), v.iterations, v.keyLen)
			if hex.EncodeToString(got) != v.wantHex {
				t.Fatalf("派生密钥不匹配\n got: %s\nwant: %s", hex.EncodeToString(got), v.wantHex)
			}
		})
	}
}

func TestHashPasswordRoundTrip(t *testing.T) {
	encoded, err := HashPassword("correct horse battery staple")
	if err != nil {
		t.Fatalf("HashPassword 出错: %v", err)
	}
	if !strings.HasPrefix(encoded, pbkdf2Scheme+"$") {
		t.Fatalf("编码前缀不对: %q", encoded)
	}
	if !VerifyPassword(encoded, "correct horse battery staple") {
		t.Fatal("正确密码校验失败")
	}
	if VerifyPassword(encoded, "wrong password") {
		t.Fatal("错误密码不应通过校验")
	}
}

func TestHashPasswordUsesRandomSalt(t *testing.T) {
	first, err := HashPassword("same-password")
	if err != nil {
		t.Fatal(err)
	}
	second, err := HashPassword("same-password")
	if err != nil {
		t.Fatal(err)
	}
	if first == second {
		t.Fatal("相同密码两次哈希不应相同（盐未随机化）")
	}
}

func TestVerifyPasswordRejectsMalformedEncoding(t *testing.T) {
	for _, encoded := range []string{
		"",
		"plaintext",
		"pbkdf2_sha256$notanumber$c2FsdA$a2V5",
		"pbkdf2_sha256$1$!!!$a2V5",
		"pbkdf2_sha256$1$c2FsdA$",
		"bcrypt$1$c2FsdA$a2V5",
	} {
		if VerifyPassword(encoded, "whatever") {
			t.Fatalf("非法编码不应通过校验: %q", encoded)
		}
	}
}

func TestHashPasswordRejectsEmpty(t *testing.T) {
	if _, err := HashPassword(""); err == nil {
		t.Fatal("空密码应报错")
	}
}

package auth

import (
	"errors"
	"strings"
	"testing"
	"time"
)

func newTestManager(now time.Time) (*TokenManager, func(time.Time)) {
	m := NewTokenManager([]byte("test-secret"), time.Minute)
	advance := func(t time.Time) { m.now = func() time.Time { return t } }
	advance(now)
	return m, advance
}

func TestTokenIssueParseRoundTrip(t *testing.T) {
	base := time.Unix(1_700_000_000, 0)
	m, _ := newTestManager(base)

	token, issued, err := m.Issue("user-1", "alice", "admin")
	if err != nil {
		t.Fatalf("Issue 出错: %v", err)
	}
	parsed, err := m.Parse(token)
	if err != nil {
		t.Fatalf("Parse 出错: %v", err)
	}
	if parsed.Subject != "user-1" || parsed.Username != "alice" || parsed.Role != "admin" {
		t.Fatalf("负载不匹配: %+v", parsed)
	}
	if parsed.ID != issued.ID || parsed.ExpiresAt != issued.ExpiresAt {
		t.Fatalf("令牌元数据不匹配: %+v vs %+v", parsed, issued)
	}
}

func TestTokenRejectsTamperedBody(t *testing.T) {
	m, _ := newTestManager(time.Unix(1_700_000_000, 0))
	token, _, err := m.Issue("user-1", "alice", "admin")
	if err != nil {
		t.Fatal(err)
	}
	body, sig, _ := strings.Cut(token, ".")
	tampered := body + "x." + sig
	if _, err := m.Parse(tampered); !errors.Is(err, ErrInvalidToken) {
		t.Fatalf("篡改负载应返回 ErrInvalidToken，得到 %v", err)
	}
}

func TestTokenRejectsWrongSecret(t *testing.T) {
	m, _ := newTestManager(time.Unix(1_700_000_000, 0))
	token, _, err := m.Issue("user-1", "alice", "admin")
	if err != nil {
		t.Fatal(err)
	}
	other := NewTokenManager([]byte("other-secret"), time.Minute)
	if _, err := other.Parse(token); !errors.Is(err, ErrInvalidToken) {
		t.Fatalf("异密钥应返回 ErrInvalidToken，得到 %v", err)
	}
}

func TestTokenExpires(t *testing.T) {
	base := time.Unix(1_700_000_000, 0)
	m, advance := newTestManager(base)
	token, _, err := m.Issue("user-1", "alice", "admin")
	if err != nil {
		t.Fatal(err)
	}
	advance(base.Add(2 * time.Minute))
	if _, err := m.Parse(token); !errors.Is(err, ErrExpiredToken) {
		t.Fatalf("过期令牌应返回 ErrExpiredToken，得到 %v", err)
	}
}

func TestTokenRevoke(t *testing.T) {
	base := time.Unix(1_700_000_000, 0)
	m, _ := newTestManager(base)
	token, claims, err := m.Issue("user-1", "alice", "admin")
	if err != nil {
		t.Fatal(err)
	}
	m.Revoke(claims.ID, time.Unix(claims.ExpiresAt, 0))
	if _, err := m.Parse(token); !errors.Is(err, ErrRevokedToken) {
		t.Fatalf("注销令牌应返回 ErrRevokedToken，得到 %v", err)
	}
}

func TestTokenRevokePrunesExpiredEntries(t *testing.T) {
	base := time.Unix(1_700_000_000, 0)
	m, _ := newTestManager(base)
	m.Revoke("old", base.Add(-time.Minute))
	if _, ok := m.revoked["old"]; ok {
		t.Fatal("过期的注销记录应被清理")
	}
}

func TestTokenRejectsMalformed(t *testing.T) {
	m, _ := newTestManager(time.Unix(1_700_000_000, 0))
	for _, token := range []string{"", "no-dot", ".", "a.", ".b", "a.b.c"} {
		if _, err := m.Parse(token); !errors.Is(err, ErrInvalidToken) {
			t.Fatalf("非法令牌 %q 应返回 ErrInvalidToken，得到 %v", token, err)
		}
	}
}

package store

import (
	"errors"
	"testing"
)

func strptr(s string) *string { return &s }
func boolptr(b bool) *bool    { return &b }

func seededStore(t *testing.T) *Store {
	t.Helper()
	s := New()
	s.SeedBuiltinRoles()
	return s
}

func TestSeedBuiltinRolesPermissions(t *testing.T) {
	s := seededStore(t)

	cases := []struct {
		role, permission string
		want             bool
	}{
		{RoleAdmin, PermUserDelete, true},
		{RoleAdmin, "anything:at:all", true}, // 通配符
		{RoleOperator, PermUserWrite, true},
		{RoleOperator, PermUserDelete, false},
		{RoleViewer, PermUserRead, true},
		{RoleViewer, PermUserWrite, false},
		{"missing", PermUserRead, false},
	}
	for _, c := range cases {
		if got := s.HasPermission(c.role, c.permission); got != c.want {
			t.Errorf("HasPermission(%q, %q) = %v，期望 %v", c.role, c.permission, got, c.want)
		}
	}
}

func TestCreateUserRejectsDuplicateAndUnknownRole(t *testing.T) {
	s := seededStore(t)
	if _, err := s.CreateUser("alice", "hash", RoleViewer); err != nil {
		t.Fatalf("创建用户失败: %v", err)
	}
	if _, err := s.CreateUser("ALICE", "hash", RoleViewer); !errors.Is(err, ErrConflict) {
		t.Fatalf("重名应返回 ErrConflict，得到 %v", err)
	}
	if _, err := s.CreateUser("bob", "hash", "ghost"); !errors.Is(err, ErrNotFound) {
		t.Fatalf("未知角色应返回 ErrNotFound，得到 %v", err)
	}
}

func TestGetUserByUsernameIsCaseInsensitive(t *testing.T) {
	s := seededStore(t)
	created, err := s.CreateUser("Alice", "hash", RoleViewer)
	if err != nil {
		t.Fatal(err)
	}
	got, err := s.GetUserByUsername("aLiCe")
