	}
}

func TestListUsersPagination(t *testing.T) {
	s := seededStore(t)
	for _, name := range []string{"u1", "u2", "u3", "u4", "u5"} {
		if _, err := s.CreateUser(name, "hash", RoleViewer); err != nil {
			t.Fatal(err)
		}
	}

	page, total := s.ListUsers(1, 2)
	if total != 5 {
