	}
}

func TestUpdateUser(t *testing.T) {
	s := seededStore(t)
	u, err := s.CreateUser("alice", "old-hash", RoleViewer)
	if err != nil {
		t.Fatal(err)
	}
	updated, err := s.UpdateUser(u.ID, UpdateInput{
		Role:         strptr(RoleOperator),
		PasswordHash: strptr("new-hash"),
	})
	if err != nil {
		t.Fatalf("更新失败: %v", err)
	}
	if updated.Role != RoleOperator || updated.PasswordHash != "new-hash" {
		t.Fatalf("更新结果不符: %+v", updated)
	}
	if _, err := s.UpdateUser(u.ID, UpdateInput{Role: strptr("ghost")}); !errors.Is(err, ErrNotFound) {
		t.Fatalf("未知角色应返回 ErrNotFound，得到 %v", err)
	}
	if _, err := s.UpdateUser("missing", UpdateInput{Active: boolptr(false)}); !errors.Is(err, ErrNotFound) {
		t.Fatalf("未知用户应返回 ErrNotFound，得到 %v", err)
	}
}

func TestLastAdminIsProtected(t *testing.T) {
	s := seededStore(t)
	admin, err := s.CreateUser("admin", "hash", RoleAdmin)
	if err != nil {
		t.Fatal(err)
	}

	if _, err := s.UpdateUser(admin.ID, UpdateInput{Role: strptr(RoleViewer)}); !errors.Is(err, ErrLastAdmin) {
		t.Fatalf("降级最后一个管理员应被拒绝，得到 %v", err)
	}
	if _, err := s.UpdateUser(admin.ID, UpdateInput{Active: boolptr(false)}); !errors.Is(err, ErrLastAdmin) {
		t.Fatalf("停用最后一个管理员应被拒绝，得到 %v", err)
	}
	if err := s.DeleteUser(admin.ID); !errors.Is(err, ErrLastAdmin) {
		t.Fatalf("删除最后一个管理员应被拒绝，得到 %v", err)
	}

	second, err := s.CreateUser("admin2", "hash", RoleAdmin)
	if err != nil {
		t.Fatal(err)
	}
	if err := s.DeleteUser(admin.ID); err != nil {
		t.Fatalf("存在第二个管理员时应可删除: %v", err)
	}
	if _, err := s.GetUser(second.ID); err != nil {
		t.Fatalf("第二个管理员不应受影响: %v", err)
	}
}

func TestCreateRoleDeduplicatesPermissions(t *testing.T) {
	s := seededStore(t)
	role, err := s.CreateRole("auditor", []string{"user:read", " user:read ", "", PermRoleRead}, false)
	if err != nil {
		t.Fatal(err)
	}
	if len(role.Permissions) != 2 {
		t.Fatalf("权限应去重后为 2 条，得到 %v", role.Permissions)
	}
	if _, err := s.CreateRole("auditor", nil, false); !errors.Is(err, ErrConflict) {
		t.Fatalf("重复角色应返回 ErrConflict，得到 %v", err)
	}
	if s.HasPermission("auditor", PermUserWrite) {
		t.Fatal("auditor 不应持有 user:write")
	}
	if !s.HasPermission("auditor", PermRoleRead) {
		t.Fatal("auditor 应持有 role:read")
	}
}

