func TestAdminUserLifecycle(t *testing.T) {
	srv, _ := newTestServer(t)
	token := login(t, srv.URL, "admin", adminPassword)

	status, body := doJSON(t, http.MethodPost, srv.URL+"/api/v1/users", token, map[string]string{
		"username": "alice", "password": "alice12345", "role": store.RoleViewer,
	})
	if status != http.StatusCreated {
		t.Fatalf("创建用户 status = %d body=%v", status, body)
	}
	aliceID, _ := body["id"].(string)
	if aliceID == "" {
		t.Fatalf("创建响应缺少 id: %v", body)
	}

	status, body = doJSON(t, http.MethodGet, srv.URL+"/api/v1/users/"+aliceID, token, nil)
	if status != http.StatusOK || body["username"] != "alice" {
		t.Fatalf("查询用户异常: status=%d body=%v", status, body)
	}

	status, body = doJSON(t, http.MethodGet, srv.URL+"/api/v1/users?page=1&page_size=10", token, nil)
	if status != http.StatusOK {
		t.Fatalf("列表 status = %d", status)
	}
	items, _ := body["items"].([]any)
	if len(items) != 2 {
		t.Fatalf("应有 2 个用户，得到 %d", len(items))
	}

	status, body = doJSON(t, http.MethodPut, srv.URL+"/api/v1/users/"+aliceID, token, map[string]string{"role": store.RoleOperator})
	if status != http.StatusOK || body["role"] != store.RoleOperator {
		t.Fatalf("更新角色异常: status=%d body=%v", status, body)
	}

	if status, _ := doJSON(t, http.MethodDelete, srv.URL+"/api/v1/users/"+aliceID, token, nil); status != http.StatusNoContent {
		t.Fatalf("删除 status = %d，期望 204", status)
	}
	if status, _ := doJSON(t, http.MethodGet, srv.URL+"/api/v1/users/"+aliceID, token, nil); status != http.StatusNotFound {
		t.Fatalf("删除后查询应 404，得到 %d", status)
	}
}

