func clearEnv(t *testing.T) {
	t.Helper()
	for _, key := range []string{"ADMIN_ADDR", "ADMIN_USERNAME", "ADMIN_PASSWORD", "ADMIN_TOKEN_SECRET", "ADMIN_TOKEN_TTL"} {
		t.Setenv(key, "")
	}
}

func TestLoadDefaults(t *testing.T) {
	clearEnv(t)

	cfg, err := Load()
	if err != nil {
		t.Fatalf("Load 出错: %v", err)
	}
	if cfg.Addr != defaultAddr {
		t.Errorf("Addr = %q，期望 %q", cfg.Addr, defaultAddr)
	}
	if cfg.AdminUsername != defaultAdminUsername {
		t.Errorf("AdminUsername = %q，期望 %q", cfg.AdminUsername, defaultAdminUsername)
	}
	if cfg.AdminPassword != defaultAdminPassword {
		t.Errorf("AdminPassword = %q，期望 %q", cfg.AdminPassword, defaultAdminPassword)
	}
	if len(cfg.TokenSecret) != 32 {
		t.Errorf("自动生成的密钥长度 = %d，期望 32", len(cfg.TokenSecret))
	}
	if !cfg.DevDefaults {
		t.Error("使用默认凭据时 DevDefaults 应为 true")
	}
	if cfg.TokenTTL != defaultTokenTTL {
		t.Errorf("TokenTTL = %v，期望 %v", cfg.TokenTTL, defaultTokenTTL)
	}
}

func TestLoadFromEnv(t *testing.T) {
	clearEnv(t)
	t.Setenv("ADMIN_ADDR", ":9999")
	t.Setenv("ADMIN_USERNAME", "root")
	t.Setenv("ADMIN_PASSWORD", "s3cret-password")
	t.Setenv("ADMIN_TOKEN_SECRET", "fixed-secret")
	t.Setenv("ADMIN_TOKEN_TTL", "30m")

	cfg, err := Load()
	if err != nil {
		t.Fatalf("Load 出错: %v", err)
	}
	if cfg.Addr != ":9999" || cfg.AdminUsername != "root" || cfg.AdminPassword != "s3cret-password" {
		t.Fatalf("配置不符: %+v", cfg)
	}
	if string(cfg.TokenSecret) != "fixed-secret" {
		t.Fatalf("TokenSecret = %q", cfg.TokenSecret)
	}
	if cfg.TokenTTL != 30*time.Minute {
		t.Fatalf("TokenTTL = %v，期望 30m", cfg.TokenTTL)
	}
	if cfg.DevDefaults {
		t.Fatal("显式提供密码与密钥时 DevDefaults 应为 false")
	}
}

